mapper.insert:
/* [신청관리 > OCR서식등록신청] - insertFormAppl */
INSERT INTO ocuoc_lfapp_m (
    APPC_ID, LEFRM_NM, APCT_ID, APCT_DPRM_CD, PRGS_ST_CD, RGSR_ID, REG_DT
) VALUES (
	SQ_OCUOC_LFAPP_M_01.NEXTVAL, #{formNm}, #{applicantUserId}, #{applDeptCd}, #{procStatCd}, #{regId}, #{regDt}
)

mapper.update:
/* [신청관리 > OCR서식등록신청] - updateFormAppl */
UPDATE  ocuoc_lfapp_m
SET
	LEFRM_NM = #{formNm},
	EDTR_ID  = #{modId},
	CHNG_DT  = #{modDt}
WHERE
	APPC_ID = #{applId}

/* [신청관리 > OCR서식등록신청] - submitFormAppl */
UPDATE  ocuoc_lfapp_m
SET
	PRGS_ST_CD = 'APPL',
	EDTR_ID  = #{modId},
	CHNG_DT  = #{modDt}
WHERE
	APPC_ID = #{applId}
 	AND PRGS_ST_CD IN ('DRAFT', 'CANC')

mapper.insert:
/* [신청관리 > OCR서식등록신청] - insertFormApplFldAiSuggest */ INSERT INTO ocuoc_lfafl_l ( FILD_ID, APPC_ID, FILD_CD, IMG_ID, UPRN_FILD_ID, ROW_NO, FILD_NM, FILD_VAL, FILD_DESC, ESN_YN, VALDTN_RULE, META_RULE, FILD_DV_CD, RADR_DV_CD, CFDC, RGSR_ID, REG_DT ) SELECT T.* FROM (
SELECT #{fld.fldId},#{applId},#{fld.fldCd},#{fld.imgId},#{fld.upFldId},#{fld.rowNo},#{fld.fldNm},#{fld.fldVal},#{fld.fldDesc}, #{fld.reqYn},#{fld.validRule},#{fld.metaRule},#{fld.fldTypeCd},#{fld.srcTypeCd},#{fld.confidence},#{regId},SYSDATE FROM DUAL
) T

/* [신청관리 > OCR서식등록신청] - insertFormApplImg */
INSERT INTO ocuoc_lfaim_l (
	IMG_ID, APPC_ID, FILE_NM, FILE_PATH, IMG_DV_CD, LNUP_SER, RGSR_ID, REG_DT
) VALUES (
			SQ_OCUOC_LFAIM_L_01.NEXTVAL, #{applId}, #{fileNm}, #{filePath}, #{imgTypeCd}, #{sortOrd}, #{regId}, #{regDt}
		 )

mapper.delete:
/* [신청관리 > OCR서식등록신청] - deleteFormApplFldMatchByImgId */
DELETE FROM ocuoc_lfafm_l M
WHERE EXISTS (
      SELECT 1
        FROM ocuoc_lfafl_l F
	   WHERE F.FILD_ID = M.FLD_ID
	     AND F.IMG_ID = #{imgId}
		 AND F.APPC_ID = #{applId}
)

mapper.insert:
/* [신청관리 > OCR서식등록신청] - insertFormApplFile */
INSERT INTO ocuoc_lfaaf_l (
	FILE_ID, APPC_ID, RADR_DV_CD, FILE_NM, FILE_PATH, FILE_SIZE, RGSR_ID, REG_DT
) VALUES (
			SQ_OCUOC_LFAAF_L_01.NEXTVAL, #{applId}, #{srcTypeCd}, #{fileNm}, #{filePath}, #{fileSize}, #{regId}, #{regDt}
		 )

/* [신청관리 > OCR서식등록신청] - insertFormApplMgrList */
INSERT INTO ocuoc_lfamg_l (
	MNGR_ID, APPC_ID, MNGR_DV_CD, MNGR_SEQNO, MNGR_USER_ID, RGSR_ID, REG_DT
)
SELECT SQ_OCUOC_LFAMG_L_01.NEXTVAL, T.*
    FROM (

		SELECT #{applId}, #{mgr.mgrTypeCd}, #{mgr.mgrSeq}, #{mgr.mgrUserId}, #{regId}, SYSDATE
		FROM DUAL

) T

/* [신청관리 > OCR서식등록신청] - insertApprvlLineList */ INSERT INTO ocuoc_aprvl_l ( APRVL_ID, APPC_ID, APPC_TYP_CD, APRVL_SEQNO, APOF_ID, APPC_STA_CD, APRVL_OPN, APRVL_DT, RGSR_ID, REG_DT ) SELECT SQ_OCUOC_APRVL_L_01.NEXTVAL, T.* FROM (
SELECT #{applId} AS APPC_ID, #{line.applTypeCd} AS APPC_TYP_CD, #{line.apprvlSeq} AS APRVL_SEQNO, #{line.apprvrUserId} AS APOF_ID, #{line.apprvlStatCd} AS APPC_STA_CD, null AS APRVL_OPN, null AS APRVL_DT, #{regId} AS RGSR_ID, SYSDATE AS REG_DT FROM DUAL
) T

/* [신청관리 > OCR서식등록신청] - insertFormApplFldMatchList */
INSERT INTO ocuoc_lfafm_l (
	MATCH_ID, FLD_ID, MATCH_FLD_ID, SORT_ORD, RGSR_ID, REG_DT
)
SELECT SQ_OCUOC_LFAFM_L_01.NEXTVAL, T.*
FROM (

	SELECT
		#{fldId}, #{matchFldId}, #{idx} + 1, #{regId}, SYSDATE
	FROM DUAL

) T
